(()=>{
 const sections=[['calendar','Календарь','admin.html','overview'],['students','Ученики','admin.html?section=students','students'],['materials','Задания и конспекты','materials.html'],['finance','Оплаты и отчёты','reports.html'],['requests','Заявки','admin.html?section=trial-requests','trial-requests']];
 window.mountAdminNavigation=active=>{
  let sidebar=document.querySelector('#admin-sidebar');
  if(!sidebar){sidebar=document.createElement('aside');sidebar.id='admin-sidebar';sidebar.className='admin-sidebar';const title=document.createElement('p');title.className='admin-sidebar-title';title.textContent='Управление';const nav=document.createElement('nav');nav.setAttribute('aria-label','Разделы администратора');for(const [id,label,href,section] of sections){const link=document.createElement('a');link.href=href;link.textContent=label;link.dataset.adminNav=id;if(section)link.addEventListener('click',event=>{if(location.pathname.endsWith('/admin.html')&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey){event.preventDefault();window.dispatchEvent(new CustomEvent('admin-navigate',{detail:section}));toggle(false)}});nav.append(link)}const profile=document.createElement('a');profile.href='account.html';profile.textContent='Мой профиль';profile.className='admin-sidebar-profile';sidebar.append(nav,profile,title);const main=document.querySelector('main'),workspace=document.createElement('div');workspace.className='admin-workspace';main.before(workspace);workspace.append(sidebar,main);const button=document.createElement('button');button.type='button';button.id='admin-menu-toggle';button.textContent='Меню администратора';button.setAttribute('aria-controls','admin-sidebar');button.setAttribute('aria-expanded','false');button.onclick=()=>toggle(button.getAttribute('aria-expanded')!=='true');document.querySelector('main').prepend(button);document.addEventListener('keydown',event=>{if(event.key==='Escape')toggle(false)})}
  document.body.classList.add('admin-shell');sidebar.querySelectorAll('[data-admin-nav]').forEach(link=>{if(link.dataset.adminNav===active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});
 };
 function toggle(open){document.querySelector('#admin-sidebar')?.classList.toggle('is-open',open);document.querySelector('#admin-menu-toggle')?.setAttribute('aria-expanded',String(open))}
})();
